"use client";

import * as React from "react";
import { Message, MessageContent } from "@/components/ui/message";
import { Bubble, BubbleContent } from "@/components/ui/bubble";
import { MessageMarkdown } from "./message-markdown";
import { ToolCallTrace } from "./tool-call-trace";
import { ThinkingIndicator } from "./thinking-indicator";
import { CopyButton } from "./copy-button";
import type { ChatMessageData, ChatTodo } from "./types";

/**
 * Role-based dispatch: the user's own turn is bubbled (align="end"),
 * matching Claude's own layout where only the human side gets bubble
 * chrome; the assistant's turn renders as plain content plus its tool-call
 * trace, no bubble — same split NotebookChat.js's ChatMessage uses.
 */
function ChatMessage({
  message,
  todos,
  projectId,
  onOpenSubagent,
  onOpenWorkspaceFile,
  onSendMessage,
}: {
  message: ChatMessageData;
  todos?: ChatTodo[];
  projectId?: string;
  onOpenSubagent?: (toolCallId: string) => void;
  onOpenWorkspaceFile?: (path: string) => void;
  onSendMessage?: (text: string) => void;
}) {
  if (message.role === "user") {
    return (
      <Message align="end">
        <MessageContent>
          <Bubble align="end">
            <BubbleContent>{message.content}</BubbleContent>
          </Bubble>
        </MessageContent>
      </Message>
    );
  }

  const hasToolCalls = (message.toolCalls?.length ?? 0) > 0;
  const isEmptyStreaming =
    !!message.isStreaming && !message.content?.trim() && !hasToolCalls;

  return (
    <Message align="start" className="group/chat-message">
      <MessageContent>
        {hasToolCalls && (
          <ToolCallTrace
            toolCalls={message.toolCalls!}
            todos={todos}
            projectId={projectId}
            onOpenSubagent={onOpenSubagent}
            onOpenWorkspaceFile={onOpenWorkspaceFile}
            onSendMessage={onSendMessage}
          />
        )}

        {isEmptyStreaming ? (
          <ThinkingIndicator />
        ) : (
          <MessageMarkdown content={message.content || ""} />
        )}

        {!message.isStreaming && message.content && (
          <div className="opacity-0 transition-opacity group-hover/chat-message:opacity-100">
            <CopyButton text={message.content} label="Copy message" />
          </div>
        )}
      </MessageContent>
    </Message>
  );
}

export { ChatMessage };

"use client";

import * as React from "react";
import {
  MessageScrollerProvider,
  MessageScroller,
  MessageScrollerContent,
  MessageScrollerViewport,
  MessageScrollerButton,
  MessageScrollerItem,
} from "@/components/ui/message-scroller";
import { cn } from "@/lib/utils";

/**
 * Auto-scrolling chat viewport — wraps the `MessageScroller*` primitive,
 * which already owns "stick to bottom while streaming" + "show a jump-to-
 * latest button once the user scrolls away" behavior. Replaces what
 * NotebookChat.js (the reference) hand-rolled with scrollContainerRef/
 * scrollAnchorRef + a manual IntersectionObserver-less effect.
 */
function ChatScroller({
  className,
  children,
  ...props
}: React.ComponentProps<typeof MessageScroller>) {
  return (
    <MessageScrollerProvider>
      <MessageScroller className={cn("flex-1", className)} {...props}>
        <MessageScrollerViewport>
          <MessageScrollerContent className="mx-auto w-full max-w-3xl px-4 py-6">
            {children}
          </MessageScrollerContent>
        </MessageScrollerViewport>
        <MessageScrollerButton />
      </MessageScroller>
    </MessageScrollerProvider>
  );
}

// Re-exported so callers wrap each message in one of these (enables
// content-visibility:auto per item) without a second import from ui/.
export { ChatScroller, MessageScrollerItem as ChatScrollerItem };

"use client";

import * as React from "react";
import {
  ArrowUpIcon,
  SquareIcon,
  PhoneXIcon,
} from "@phosphor-icons/react";
import { InputGroup, InputGroupTextarea, InputGroupAddon, InputGroupButton } from "@/components/ui/input-group";

// Same "start voice mode" glyph NotebookChat.js's ComposerForm uses (a
// waveform, not a generic microphone) — inlined to match it exactly rather
// than substituting a similar-but-different icon from phosphor's set.
// VoiceTab's "Start voice call" button renders this; the composer itself no
// longer shows a voice-mode toggle (nothing in the Playground wires it, so
// it was a dead button), so VoiceModeIcon lives here only as a shared glyph.
function VoiceModeIcon(props: React.SVGProps<SVGSVGElement>) {
  return (
    <svg
      width="16"
      height="16"
      viewBox="0 0 24 24"
      fill="none"
      stroke="currentColor"
      strokeWidth={2}
      strokeLinecap="round"
      {...props}
    >
      <path d="M2 10v3" />
      <path d="M6 6v11" />
      <path d="M10 3v18" />
      <path d="M14 8v8" />
      <path d="M18 5v14" />
      <path d="M22 10v3" />
    </svg>
  );
}

/**
 * Auto-resizing composer. The trailing action row is ALWAYS present, so the
 * composer keeps one steady height whether it is idle, streaming text, or
 * mid-voice-call — dropping the row when a surface has no voice button used
 * to shrink the idle composer into a short stub, so it is never conditionally
 * unmounted. Which action the row shows is computed by the caller:
 *
 *   streaming   → stop generating
 *   voice live  → stop the call, or send the typed text into the call
 *   default     → send message (dimmed until there is text to send)
 *
 * Deliberately no voice-mode toggle on the composer itself: the surfaces in
 * this app that support voice run it in their own tab (VoiceTab), so an idle
 * "start voice" waveform would be a dead button. VoiceTab drives the live
 * states via isVoiceActive instead.
 *
 * The empty-state send is dimmed with `pointer-events-none` + reduced opacity
 * rather than a native `disabled` attribute — InputGroup greys out its WHOLE
 * contents via `has-disabled` when any child is disabled, which would wash
 * out the text field too.
 *
 * Deliberately no custom rounding/background overrides here — `InputGroup`/
 * `InputGroupButton` already carry this app's actual look (sharp
 * `rounded-none` everywhere, `Button`'s own variant colors), stacking a
 * borrowed rounded-pill/rounded-full treatment on top of them is exactly
 * what looked inconsistent and over-padded before.
 */
function ChatComposer({
  value,
  onChange,
  onSend,
  onStop,
  onStopVoice,
  onSendToVoice,
  isStreaming = false,
  isVoiceActive = false,
  disabled = false,
  placeholder,
}: {
  value: string;
  onChange: (value: string) => void;
  onSend: () => void;
  onStop?: () => void;
  onStopVoice?: () => void;
  onSendToVoice?: (text: string) => void;
  isStreaming?: boolean;
  isVoiceActive?: boolean;
  disabled?: boolean;
  placeholder?: string;
}) {
  const trimmed = value.trim();

  const submit = () => {
    if (!trimmed) return;
    if (isVoiceActive) {
      onSendToVoice?.(trimmed);
    } else if (!isStreaming) {
      onSend();
    }
  };

  return (
    <form
      onSubmit={(e) => {
        e.preventDefault();
        submit();
      }}
    >
      <InputGroup>
        <InputGroupTextarea
          value={value}
          onChange={(e) => onChange(e.target.value)}
          onKeyDown={(e) => {
            if (e.key === "Enter" && !e.shiftKey) {
              e.preventDefault();
              submit();
            }
          }}
          placeholder={placeholder ?? (isVoiceActive ? "Type to voice…" : "Ask anything…")}
          rows={1}
          disabled={disabled}
          className="max-h-40"
        />

        <InputGroupAddon align="block-end" className="justify-end">
          {isStreaming ? (
            <InputGroupButton
              type="button"
              variant="secondary"
              size="icon-sm"
              aria-label="Stop generating"
              onClick={onStop}
            >
              <SquareIcon weight="fill" />
            </InputGroupButton>
          ) : isVoiceActive ? (
            trimmed ? (
              <InputGroupButton type="submit" variant="default" size="icon-sm" aria-label="Send to voice">
                <ArrowUpIcon />
              </InputGroupButton>
            ) : (
              <InputGroupButton
                type="button"
                variant="destructive"
                size="icon-sm"
                aria-label="Stop voice"
                onClick={onStopVoice}
              >
                <PhoneXIcon />
              </InputGroupButton>
            )
          ) : (
            <InputGroupButton
              type="submit"
              variant="default"
              size="icon-sm"
              aria-label="Send message"
              // Dim but not natively disabled (see note above): pointer-events
              // off so an empty click no-ops and focuses the field instead.
              className={trimmed ? undefined : "pointer-events-none opacity-40"}
            >
              <ArrowUpIcon />
            </InputGroupButton>
          )}
        </InputGroupAddon>
      </InputGroup>
    </form>
  );
}

export { ChatComposer, VoiceModeIcon };

"use client";

import * as React from "react";
import type { Icon } from "@phosphor-icons/react";
import { Empty, EmptyHeader, EmptyTitle, EmptyDescription, EmptyContent } from "@/components/ui/empty";
import { Button } from "@/components/ui/button";

export interface ChatStarterPrompt {
  label: string;
  icon: Icon;
  template: string;
}

/**
 * Blank-conversation state — a title plus starter-prompt pills that
 * prefill (not auto-send) the composer, matching NotebookChat.js's
 * STARTER_PROMPTS pattern, generalized (no notebook/course wording baked
 * in — the caller supplies its own prompts and copy).
 */
function ChatEmptyState({
  title,
  description,
  starterPrompts,
  onSelectPrompt,
}: {
  title: string;
  description?: string;
  starterPrompts?: ChatStarterPrompt[];
  onSelectPrompt?: (template: string) => void;
}) {
  return (
    <Empty className="flex-1 border-none">
      <EmptyHeader>
        <EmptyTitle>{title}</EmptyTitle>
        {description && <EmptyDescription>{description}</EmptyDescription>}
      </EmptyHeader>
      {starterPrompts?.length ? (
        <EmptyContent>
          <div className="flex flex-wrap items-center justify-center gap-2">
            {starterPrompts.map(({ label, icon: PromptIcon, template }) => (
              <Button
                key={label}
                type="button"
                variant="outline"
                size="sm"
                className="rounded-full"
                onClick={() => onSelectPrompt?.(template)}
              >
                <PromptIcon /> {label}
              </Button>
            ))}
          </div>
        </EmptyContent>
      ) : null}
    </Empty>
  );
}

export { ChatEmptyState };

"use client";

import * as React from "react";
import { Streamdown } from "streamdown";
import remarkGfm from "remark-gfm";
import { code } from "@streamdown/code";
import { cn } from "@/lib/utils";

/**
 * Every markdown render in the library goes through this one wrapper.
 * `Streamdown` is purpose-built for partial/incomplete markdown mid-stream
 * (unclosed code fences, half-written tables) — the exact problem the
 * NotebookChat.js reference solved by hand, switching between a raw
 * streaming renderer and a full block renderer once a message finished.
 * One renderer, used for both states, is simpler and doesn't need that split.
 */
function MessageMarkdown({
  className,
  content,
}: {
  className?: string;
  content: string;
}) {
  return (
    <Streamdown
      className={cn(
        "max-w-none text-xs/relaxed text-foreground [&>*:first-child]:mt-0 [&>*:last-child]:mb-0",
        "[&_a]:text-primary [&_a]:underline [&_a]:underline-offset-4",
        // Only inline code gets our chip styling — fenced code blocks are
        // fully owned by Streamdown's own code-block renderer (header bar +
        // token colors from the `code` plugin); adding another border/bg/
        // padding layer around its <pre>/<code> just nests boxes inside
        // boxes.
        "[&_code:not(pre_code)]:rounded-none [&_code:not(pre_code)]:bg-muted [&_code:not(pre_code)]:px-1 [&_code:not(pre_code)]:py-0.5 [&_code:not(pre_code)]:text-xs",
        "[&_h1]:mt-4 [&_h1]:mb-2 [&_h1]:text-sm [&_h1]:font-semibold",
        "[&_h2]:mt-4 [&_h2]:mb-2 [&_h2]:text-sm [&_h2]:font-semibold",
        "[&_h3]:mt-3 [&_h3]:mb-1.5 [&_h3]:text-xs [&_h3]:font-semibold",
        "[&_ol]:my-2 [&_ol]:list-decimal [&_ol]:pl-5 [&_ul]:my-2 [&_ul]:list-disc [&_ul]:pl-5",
        "[&_p]:my-2",
        // Wrap fenced code instead of letting it scroll horizontally —
        // a long unbroken line otherwise forces the code block wider than
        // its flex ancestors are willing to shrink to, which overflows the
        // whole page sideways on narrow (mobile) viewports.
        "[&_[data-streamdown=code-block-body]]:overflow-x-visible!",
        "[&_[data-streamdown=code-block-body]_pre]:whitespace-pre-wrap! [&_[data-streamdown=code-block-body]_pre]:break-words!",
        "[&_[data-streamdown=code-block-body]_code]:whitespace-pre-wrap! [&_[data-streamdown=code-block-body]_code]:break-words!",
        "[&_table]:my-2 [&_td]:border [&_td]:border-border [&_td]:px-2 [&_td]:py-1 [&_th]:border [&_th]:border-border [&_th]:px-2 [&_th]:py-1",
        className
      )}
      remarkPlugins={[remarkGfm]}
      plugins={{ code }}
    >
      {content}
    </Streamdown>
  );
}

export { MessageMarkdown };

"use client";

import * as React from "react";
import { cn } from "@/lib/utils";

// Claude Code's own spinner — cycles forward through this sequence then
// back, never a generic spin icon. Exact frame set from the reference
// (NotebookChat.js's AssistantThinking).
const CLAUDE_SPINNER_BASE = ["·", "✢", "*", "✶", "✻", "✽"];
const CLAUDE_SPINNER_FRAMES = [
  ...CLAUDE_SPINNER_BASE,
  ...[...CLAUDE_SPINNER_BASE].reverse(),
];

/**
 * Shown for the gap before the first token arrives — Claude Code's exact
 * spinner (no avatar/icon), with a live elapsed timer once it's taking a
 * while, same as claude.ai and the NotebookChat.js reference.
 */
function ThinkingIndicator({ className }: { className?: string }) {
  const [frame, setFrame] = React.useState(0);
  const [elapsed, setElapsed] = React.useState(0);

  React.useEffect(() => {
    const id = setInterval(
      () => setFrame((f) => (f + 1) % CLAUDE_SPINNER_FRAMES.length),
      120
    );
    return () => clearInterval(id);
  }, []);

  React.useEffect(() => {
    const start = Date.now();
    const id = setInterval(
      () => setElapsed(Math.floor((Date.now() - start) / 1000)),
      1000
    );
    return () => clearInterval(id);
  }, []);

  return (
    <div
      role="status"
      aria-live="polite"
      aria-label="Thinking"
      className={cn(
        "inline-flex items-center gap-2 py-2 text-xs leading-none text-muted-foreground select-none",
        className
      )}
    >
      <span className="w-4 text-center font-mono text-sm text-foreground" aria-hidden>
        {CLAUDE_SPINNER_FRAMES[frame]}
      </span>
      <span className="font-medium tracking-tight">
        Thinking
        {elapsed > 2 ? ` · ${elapsed}s` : <span className="animate-pulse">…</span>}
      </span>
    </div>
  );
}

export { ThinkingIndicator };

"use client";

import * as React from "react";
import { ItemGroup } from "@/components/ui/item";
import { ToolCallCard } from "./tool-call-card";
import { McpAppRenderer } from "./mcp-app-renderer";
import type { ChatToolCall, ChatTodo } from "./types";

function parsePresentedFilePath(result: string | undefined): string | null {
  if (!result) return null;
  try {
    const parsed = JSON.parse(result);
    if (parsed?.status === "success" && typeof parsed.filePath === "string") {
      return parsed.filePath;
    }
  } catch {
    // malformed result — nothing to present
  }
  return null;
}

function ToolCallTrace({
  toolCalls,
  todos,
  projectId,
  onOpenSubagent,
  onOpenWorkspaceFile,
  onSendMessage,
}: {
  toolCalls: ChatToolCall[];
  todos?: ChatTodo[];
  projectId?: string;
  onOpenSubagent?: (toolCallId: string) => void;
  onOpenWorkspaceFile?: (path: string) => void;
  onSendMessage?: (text: string) => void;
}) {
  // Fires onOpenWorkspaceFile once per completed present_file call, not on
  // every render — a plain call inside the render/map below would re-fire
  // on every re-render and update state while rendering.
  const notifiedRef = React.useRef(new Set<string>());
  React.useEffect(() => {
    if (!onOpenWorkspaceFile) return;
    for (const tc of toolCalls) {
      if (tc.name !== "present_file" || notifiedRef.current.has(tc.id)) continue;
      const path = parsePresentedFilePath(tc.result);
      if (path) {
        notifiedRef.current.add(tc.id);
        onOpenWorkspaceFile(path);
      }
    }
  }, [toolCalls, onOpenWorkspaceFile]);

  if (!toolCalls.length) return null;

  // Group consecutive regular tool calls together in ItemGroup,
  // and render MCP App tool calls as prominent standalone blocks.
  const elements: React.ReactNode[] = [];
  let currentGroup: ChatToolCall[] = [];

  const flushGroup = () => {
    if (currentGroup.length > 0) {
      const groupKey = currentGroup[0].id;
      elements.push(
        <ItemGroup key={`group-${groupKey}`} className="gap-1.5!">
          {currentGroup.map((tc) => (
            <ToolCallCard
              key={tc.id}
              toolCall={tc}
              todos={todos}
              onOpenSubagent={onOpenSubagent}
            />
          ))}
        </ItemGroup>
      );
      currentGroup = [];
    }
  };

  for (const tc of toolCalls) {
    if (tc.mcpApp?.resourceUri && tc.mcpApp?.mcpId) {
      flushGroup();
      elements.push(
        <div key={`mcp-app-${tc.id}`} className="w-full my-1.5">
          <McpAppRenderer
            projectId={projectId || ""}
            mcpId={tc.mcpApp.mcpId}
            resourceUri={tc.mcpApp.resourceUri}
            toolName={tc.name}
            tool={tc}
            onSendMessage={onSendMessage}
          />
        </div>
      );
    } else {
      currentGroup.push(tc);
    }
  }
  flushGroup();

  return <div className="flex flex-col gap-1.5 mb-2">{elements}</div>;
}

export { ToolCallTrace };

"use client";

import * as React from "react";
import {
  WrenchIcon,
  RobotIcon,
  WarningCircleIcon,
  CaretDownIcon,
} from "@phosphor-icons/react";
import {
  Collapsible,
  CollapsibleTrigger,
  CollapsibleContent,
} from "@/components/ui/collapsible";
import { Item, ItemMedia, ItemContent, ItemTitle } from "@/components/ui/item";
import { Spinner } from "@/components/ui/spinner";
import { Button } from "@/components/ui/button";
import { cn } from "@/lib/utils";
import { TodoChecklist } from "./todo-checklist";
import type { ChatToolCall, ChatTodo } from "./types";

const TOOL_LABELS: Record<string, string> = {
  write_todos: "Planning next steps",
  task: "Delegating to a helper",
  present_file: "Sharing a file",
  read_file: "Reading a file",
  write_file: "Saving a file",
  edit_file: "Updating a file",
  ls: "Looking through files",
  glob: "Looking through files",
  grep: "Searching files",
};

function humanizeToolName(name: string): string {
  return TOOL_LABELS[name] ?? name.replace(/_/g, " ").replace(/\b\w/g, (c) => c.toUpperCase());
}

function formatJson(raw: string | undefined): string {
  if (!raw) return "";
  try {
    return JSON.stringify(JSON.parse(raw), null, 2);
  } catch {
    return raw;
  }
}

/** One collapsible card for a single tool call — icon/label/status header, expandable args+result. */
function ToolCallCard({
  toolCall,
  todos,
  onOpenSubagent,
}: {
  toolCall: ChatToolCall;
  todos?: ChatTodo[];
  onOpenSubagent?: (toolCallId: string) => void;
}) {
  const [open, setOpen] = React.useState(false);
  const isTask = toolCall.name === "task";
  const isTodos = toolCall.name === "write_todos";
  const isPending = toolCall.status === "running";
  const isError = toolCall.status === "error";
  const label = humanizeToolName(toolCall.name);

  return (
    <Collapsible open={open} onOpenChange={setOpen}>
      <Item
        variant="outline"
        size="sm"
        className={cn(
          "flex-col items-stretch",
          isError && "border-destructive/30"
        )}
      >
        <CollapsibleTrigger
          render={
            <button type="button" className="flex w-full items-center gap-2.5 text-left" />
          }
        >
          <ItemMedia variant="icon">
            {isError ? (
              <WarningCircleIcon className="text-destructive" />
            ) : isPending ? (
              <Spinner className="text-primary" />
            ) : isTask ? (
              <RobotIcon />
            ) : (
              <WrenchIcon />
            )}
          </ItemMedia>
          <ItemContent>
            <ItemTitle className={cn(isError && "text-destructive")}>
              {label}
              {isPending ? "…" : ""}
            </ItemTitle>
          </ItemContent>
          <CaretDownIcon
            className={cn("size-3.5 shrink-0 text-muted-foreground transition-transform", open && "rotate-180")}
          />
        </CollapsibleTrigger>

        {!open && isTodos && todos?.length ? (
          <div className="mt-2 pl-8">
            <TodoChecklist todos={todos} compact />
          </div>
        ) : null}

        <CollapsibleContent>
          <div className="mt-2.5 flex flex-col gap-2.5 border-t border-border pt-2.5">
            {toolCall.args && (
              <div>
                <div className="mb-1 text-xs font-semibold text-muted-foreground">Input</div>
                <pre className="max-h-32 overflow-auto rounded-none border border-border bg-muted p-2 text-xs leading-relaxed wrap-break-word whitespace-pre-wrap">
                  {formatJson(toolCall.args)}
                </pre>
              </div>
            )}
            {toolCall.result && (
              <div>
                <div className="mb-1 text-xs font-semibold text-muted-foreground">Result</div>
                <pre
                  className={cn(
                    "max-h-40 overflow-auto rounded-none border p-2 text-xs leading-relaxed wrap-break-word whitespace-pre-wrap",
                    isError
                      ? "border-destructive/30 bg-destructive/10 text-destructive"
                      : "border-border bg-muted"
                  )}
                >
                  {formatJson(toolCall.result)}
                </pre>
              </div>
            )}
            {isTask && onOpenSubagent && (
              <Button
                type="button"
                variant="secondary"
                size="sm"
                className="self-start"
                onClick={(e) => {
                  e.stopPropagation();
                  onOpenSubagent(toolCall.id);
                }}
              >
                <RobotIcon /> View subagent
              </Button>
            )}
          </div>
        </CollapsibleContent>
      </Item>
    </Collapsible>
  );
}

export { ToolCallCard, humanizeToolName };

"use client";

import * as React from "react";
import { CheckIcon, CircleIcon, CircleDashedIcon } from "@phosphor-icons/react";
import { cn } from "@/lib/utils";
import type { ChatTodo } from "./types";

function TodoChecklist({
  todos,
  compact = false,
}: {
  todos: ChatTodo[];
  compact?: boolean;
}) {
  if (!todos?.length) return null;

  return (
    <ul className={cn("flex flex-col gap-1", compact ? "gap-0.5" : "gap-1")}>
      {todos.map((todo, i) => (
        <li
          key={i}
          className={cn(
            "flex items-start gap-2 text-xs",
            todo.status === "completed" && "text-muted-foreground line-through",
            todo.status === "in_progress" && "text-foreground font-medium"
          )}
        >
          <span className="mt-0.5 flex size-3.5 shrink-0 items-center justify-center">
            {todo.status === "completed" ? (
              <CheckIcon className="size-3.5 text-primary" />
            ) : todo.status === "in_progress" ? (
              <CircleDashedIcon className="size-3.5 animate-spin text-primary" />
            ) : (
              <CircleIcon className="size-3.5 text-muted-foreground" />
            )}
          </span>
          <span className="min-w-0 flex-1 wrap-break-word">{todo.content}</span>
        </li>
      ))}
    </ul>
  );
}

export { TodoChecklist };

"use client";

import * as React from "react";
import {
  WarningCircleIcon,
  ArrowsOutIcon,
  ArrowsInIcon,
  AppWindowIcon,
} from "@phosphor-icons/react";
import {
  AppBridge,
  PostMessageTransport,
} from "@modelcontextprotocol/ext-apps/app-bridge";
import { readProjectMcpResource, callProjectMcpTool } from "@/lib/api/projects";
import { Spinner } from "@/components/ui/spinner";
import { cn } from "@/lib/utils";

function parseJsonObject(value?: string): Record<string, unknown> {
  if (!value || typeof value !== "string") return {};
  try {
    const parsed = JSON.parse(value);
    return parsed && typeof parsed === "object" ? (parsed as Record<string, unknown>) : {};
  } catch {
    return {};
  }
}

function buildToolResultPayload(tool?: { result?: string }) {
  let structuredContent: unknown = undefined;
  if (tool?.result) {
    try {
      structuredContent = JSON.parse(tool.result);
    } catch {
      // plain text fallback
    }
  }

  const content = [
    {
      type: "text" as const,
      text: typeof tool?.result === "string" ? tool.result : "",
    },
  ];

  return structuredContent !== undefined
    ? { content, structuredContent }
    : { content };
}

export interface McpAppRendererProps {
  projectId: string;
  mcpId: string;
  resourceUri: string;
  toolName?: string;
  tool?: {
    args?: string;
    result?: string;
    status: "running" | "done" | "error";
  };
  className?: string;
  height?: number;
  expanded?: boolean;
  onSendMessage?: (text: string) => void;
}

/**
 * McpAppRenderer — renders an interactive MCP App widget inside a sandboxed
 * iframe, connected via AppBridge JSON-RPC-over-postMessage.
 */
export function McpAppRenderer({
  projectId,
  mcpId,
  resourceUri,
  toolName,
  tool,
  className,
  height = 450,
  expanded: initialExpanded = true,
  onSendMessage,
}: McpAppRendererProps) {
  const iframeRef = React.useRef<HTMLIFrameElement | null>(null);
  const bridgeRef = React.useRef<AppBridge | null>(null);
  const resultSentRef = React.useRef(false);
  const onSendMessageRef = React.useRef(onSendMessage);
  onSendMessageRef.current = onSendMessage;
  const [html, setHtml] = React.useState<string | null>(null);
  const [loading, setLoading] = React.useState(true);
  const [error, setError] = React.useState<string | null>(null);
  const [expanded, setExpanded] = React.useState(initialExpanded);
  const [contentHeight, setContentHeight] = React.useState<number | null>(null);

  // 1. Fetch the widget HTML from the MCP server
  React.useEffect(() => {
    if (!projectId || !mcpId || !resourceUri) {
      setError("Missing project ID, MCP ID, or resource URI");
      setLoading(false);
      return;
    }

    let cancelled = false;
    setLoading(true);
    setError(null);
    setHtml(null);
    setContentHeight(null);

    readProjectMcpResource(projectId, mcpId, resourceUri)
      .then((res) => {
        if (cancelled) return;
        const data = res.data?.data;
        if (!data?.text) {
          throw new Error("Empty resource response from MCP server");
        }
        setHtml(data.text);
        setLoading(false);
      })
      .catch((err) => {
        if (cancelled) return;
        const msg = err?.response?.data?.message || err.message || "Failed to load MCP App";
        setError(msg);
        setLoading(false);
      });

    return () => {
      cancelled = true;
    };
  }, [projectId, mcpId, resourceUri]);

  // 2. Wire up AppBridge and load HTML into sandboxed iframe
  React.useEffect(() => {
    if (!html || !iframeRef.current) return;

    const iframe = iframeRef.current;
    resultSentRef.current = false;

    const bridge = new AppBridge(
      null,
      { name: "persona-platform", version: "1.0.0" },
      {
        message: { text: {} },
        openLinks: {},
        serverTools: {},
        serverResources: {},
        updateModelContext: { text: {} },
      },
      {
        hostContext: {
          theme:
            typeof document !== "undefined" && document.documentElement.classList.contains("dark")
              ? "dark"
              : "light",
          platform: "web",
          displayMode: "inline",
          availableDisplayModes: ["inline"],
        },
      }
    );

    bridge.oncalltool = async (params: { name: string; arguments?: Record<string, unknown> }) => {
      const res = await callProjectMcpTool(projectId, mcpId, params.name, params.arguments || {});
      return res.data?.data;
    };

    bridge.onreadresource = async (params: { uri: string }) => {
      const res = await readProjectMcpResource(projectId, mcpId, params.uri);
      const data = res.data?.data;
      return {
        contents: [
          {
            uri: params.uri,
            mimeType: data?.mimeType || "text/html",
            text: data?.text || "",
          },
        ],
      };
    };

    bridge.onopenlink = async ({ url }: { url: string }) => {
      if (typeof window !== "undefined") {
        window.open(url, "_blank", "noopener,noreferrer");
      }
      return {};
    };

    bridge.onmessage = async ({ content }) => {
      if (Array.isArray(content)) {
        const text = content
          .filter(
            (b): b is { type: "text"; text: string } =>
              b?.type === "text" && typeof (b as { text?: unknown }).text === "string"
          )
          .map((b) => b.text)
          .join("\n")
          .trim();
        if (text) {
          onSendMessageRef.current?.(text);
        }
      }
      return {};
    };
    bridge.onupdatemodelcontext = async () => ({});

    bridge.oninitialized = () => {
      bridge.sendToolInput({ arguments: parseJsonObject(tool?.args) });
      if (tool?.status === "done" && typeof tool?.result === "string") {
        resultSentRef.current = true;
        bridge.sendToolResult(buildToolResultPayload(tool));
      }
    };

    const handleSizeChange = ({ height: newHeight }: { height?: number }) => {
      if (newHeight !== undefined && newHeight !== null) {
        setContentHeight(newHeight);
      }
    };
    bridge.addEventListener("sizechange", handleSizeChange);

    let cancelled = false;
    if (iframe.contentWindow) {
      const transport = new PostMessageTransport(iframe.contentWindow, iframe.contentWindow);
      bridge
        .connect(transport)
        .then(() => {
          if (cancelled) return;
          iframe.srcdoc = html;
        })
        .catch((err) => {
          if (cancelled) return;
          setError(err?.message || "Failed to connect to MCP App bridge");
        });
    }

    bridgeRef.current = bridge;

    return () => {
      cancelled = true;
      bridgeRef.current = null;
      bridge.removeEventListener("sizechange", handleSizeChange);
      bridge.close?.();
    };
  }, [html, projectId, mcpId]);

  // 3. Forward tool result once it arrives
  React.useEffect(() => {
    const bridge = bridgeRef.current;
    if (!bridge || resultSentRef.current) return;
    if (tool?.status !== "done" || typeof tool?.result !== "string") return;
    resultSentRef.current = true;
    bridge.sendToolResult(buildToolResultPayload(tool));
  }, [tool?.status, tool?.result]);

  const toggleExpanded = React.useCallback(() => {
    setExpanded((prev) => !prev);
  }, []);

  if (error) {
    return (
      <div
        className={cn(
          "rounded-none border border-destructive/30 bg-destructive/10 p-4 text-destructive",
          className
        )}
      >
        <div className="flex items-start gap-2.5">
          <WarningCircleIcon className="size-5 shrink-0 mt-0.5" />
          <div className="min-w-0">
            <p className="text-xs font-semibold">Failed to load MCP App</p>
            <p className="mt-1 text-xs opacity-80">{error}</p>
          </div>
        </div>
      </div>
    );
  }

  return (
    <div
      className={cn(
        "group relative rounded-none border border-border bg-card overflow-hidden transition-all",
        className
      )}
    >
      {/* Header bar */}
      <div className="flex items-center justify-between border-b border-border bg-muted/40 px-3 py-1.5 text-xs text-muted-foreground">
        <div className="flex items-center gap-1.5 font-mono text-[11px] truncate">
          <AppWindowIcon className="size-3.5 text-primary shrink-0" />
          <span className="font-semibold text-foreground">{toolName || "MCP App"}</span>
          <span className="text-muted-foreground truncate">({resourceUri})</span>
        </div>

        <button
          type="button"
          onClick={toggleExpanded}
          className="flex size-6 items-center justify-center text-muted-foreground hover:text-foreground hover:bg-muted transition-colors cursor-pointer"
          title={expanded ? "Collapse" : "Expand"}
        >
          {expanded ? (
            <ArrowsInIcon className="size-3.5" />
          ) : (
            <ArrowsOutIcon className="size-3.5" />
          )}
        </button>
      </div>

      {/* Loading state */}
      {loading && (
        <div
          className="flex flex-col items-center justify-center gap-2 p-8 text-muted-foreground"
          style={{ height: `${height}px` }}
        >
          <Spinner className="size-5 text-primary" />
          <p className="text-xs">Loading MCP App…</p>
        </div>
      )}

      {/* Sandboxed iframe */}
      <iframe
        ref={iframeRef}
        sandbox="allow-scripts allow-forms"
        className={cn(
          "w-full border-0 transition-[height] duration-200 ease-in-out bg-white dark:bg-zinc-950",
          loading && "hidden"
        )}
        style={
          !loading
            ? {
                height:
                  contentHeight !== null
                    ? `${contentHeight}px`
                    : expanded
                      ? "calc(80vh - 8rem)"
                      : `${height}px`,
                maxHeight: expanded ? "calc(90vh - 6rem)" : `${height}px`,
              }
            : undefined
        }
        title={`MCP App: ${toolName || resourceUri}`}
      />
    </div>
  );
}

